using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SmartCampusServicePortal.Data; using SmartCampusServicePortal.Models; namespace SmartCampusServicePortal.Controllers; public class HomeController(ApplicationDbContext db):Controller{public async Task<IActionResult> Index(){var a=await db.ServiceRequests.OrderByDescending(x=>x.SubmissionDate).ToListAsync();return View(new DashboardViewModel{TotalRequests=a.Count,PendingRequests=a.Count(x=>x.Status=="Pending"),InProgressRequests=a.Count(x=>x.Status=="In Progress"),CompletedRequests=a.Count(x=>x.Status=="Completed"),RecentRequests=a.Take(8).ToList()});}}